            let ((pw, ph), (mw, mh)) = ana_pencere_boyutu(wa.size.width as f64 / sf, wa.size.height as f64 / sf);
            let _ = w.set_min_size(Some(tauri::LogicalSize::new(mw, mh)));
            let _ = w.set_size(tauri::LogicalSize::new(pw, ph));
